import sys

def main():
    aa = int(sys.stdin.readline())
    ttl = 0
    for i in range(2, aa):
        k = aa
        while k > 0:
            ttl += k % i
            k //= i
            if k < i:
                ttl += k
                break
    l = aa - 2
    for i in range(l, 1, -1):
        if ttl % i == 0 and l % i == 0:
            ttl //= i
            l //= i
            break
    print(f"{ttl}/{l}")

if __name__ == "__main__":
    main()

